#include <bits/stdc++.h>
using namespace std;

bool isLetter(char c) {
    return c >= 'A' && c <= 'Z';
}

bool isDigit(char c) {
    return c >= '0' && c <= '9';
}

int main() {
    string s;
    cin >> s;

    if (s.size() == 8) {
        bool ok = true;
        for (int i = 0; i < 3; i++) {
            if (!isLetter(s[i])) ok = false;
        }
        if (s[3] != '-') ok = false;
        for (int i = 4; i < 8; i++) {
            if (!isDigit(s[i])) ok = false;
        }
        if (ok) {
            cout << 1 << '\n';
            return 0;
        }
    }

    if (s.size() == 7) {
        bool ok = true;
        for (int i = 0; i < 3; i++) {
            if (!isLetter(s[i])) ok = false;
        }
        if (!isDigit(s[3])) ok = false;
        if (!isLetter(s[4])) ok = false;
        for (int i = 5; i < 7; i++) {
            if (!isDigit(s[i])) ok = false;
        }
        if (ok) {
            cout << 2 << '\n';
            return 0;
        }
    }

    cout << 0 << '\n';
    return 0;
}
